INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('chen-chunqiu','陈','["陈","陈国"]',NULL,'{"periods":[{"rank":"侯","start":{"year":-1045,"month":1,"confidence":"approximate_year"},"end":{"year":-478,"month":12,"confidence":"year"}}]}','cn','east_asia',-1045,1,NULL,'approximate_year',-478,12,NULL,'year',-12528,-5713,'ochre',NULL,NULL,'周武王封舜后于陈，陈国以宛丘为都。前534年楚灭陈并置县，前529年复国；前478年楚惠王杀陈湣公，陈亡。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r0','满','chen-chunqiu','["胡公满"]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','舜裔，周武王克商后受封于陈，建国并奉舜祀。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','胡',NULL,'胡公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r1','犀侯','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','胡公之子，继位为陈君；早期世系事迹主要见《史记·陈杞世家》。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','申',NULL,'申公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r10','圉','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','平公之子，娶蔡女并生佗；卒后长子鲍继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','文',NULL,'文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r11','鲍','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文公之子，在位三十八年。卒后弟佗在蔡人支持下即位，陈国继承与政局转入动荡。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','桓',NULL,'桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r12','佗','chen-chunqiu','["陈侯佗","厉公"]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','桓公之弟，母为蔡女。桓公卒后蔡人杀太子免等人而立佗；在位不足一年，后为蔡人所杀。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]',NULL,NULL,'佗','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r13','跃','chen-chunqiu','["利公"]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','桓公之子。蔡人杀佗后立跃；《史记》记其在位七年，后由弟林继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','厉',NULL,'厉公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r14','林','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','厉公之弟。继位七年而卒，少弟杵臼继位为宣公。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','庄',NULL,'庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r15','杵臼','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','庄公之弟，在位四十五年。杀太子御寇而改立宠姬之子款；公子完因与御寇交好避祸奔齐，成为田氏后来的先祖。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','宣',NULL,'宣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r16','款','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','宣公之子，承继为陈君；卒后子朔继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','穆',NULL,'穆公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r17','朔','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','穆公之子，卒后子平国继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','共',NULL,'共公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r18','平国','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','共公之子。与大夫孔宁、仪行父皆与夏姬私通；前599年被夏征舒射杀，太子午出奔晋国。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','灵',NULL,'灵公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r19','征舒','chen-chunqiu','["夏征舒","陈侯征舒"]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','夏御叔与夏姬之子，陈宣公后裔。前599年射杀陈灵公后自立为陈侯，同年楚庄王伐陈并杀征舒。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]',NULL,NULL,'征舒','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r2','皋羊','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','申公之弟，承继为陈君；其后由申公之子突继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','相',NULL,'相公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r20','午','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','灵公之子。前599年灵公死后出奔晋国，前598年楚庄王迎立其归陈复位；在位三十年，卒后子弱继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','成',NULL,'成公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r21','弱','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','成公之子。前566年楚围陈；晚年宠爱公子留，司徒招杀太子偃师并立留，哀公随后自缢。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','哀',NULL,'哀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r22','留','chen-chunqiu','["陈侯留"]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','哀公之子。前534年司徒招在杀太子偃师后立留为君；当年楚军灭陈，留出奔郑。史书记其在位自三月至十一月，月份为古历记载，未直接换算为公历月。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]',NULL,NULL,'留','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r23','吴','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','悼太子师之子、哀公之孙。前529年楚平王恢复陈国并立吴为陈侯；陈国由楚县复国。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','惠',NULL,'惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r24','柳','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','惠公之子。吴国两度召其赴吴，最终将他扣留；柳客死吴国后，子越继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','怀',NULL,'怀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r25','越','chen-chunqiu','["闵公"]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','怀公之子。前496年陈与楚灭顿，前489年吴攻陈而楚救陈；前478年楚军攻陈，楚惠王杀越，陈国灭亡。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','湣',NULL,'湣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r3','突','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','申公之子，承继相公为陈君，后由其子圉戎继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','孝',NULL,'孝公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r4','圉戎','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','孝公之子，周厉王时期在位；其子宁继位为幽公。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','慎',NULL,'慎公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r5','宁','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','慎公之子。其在位年代处于可与周王年及春秋纪年相互参照的早期阶段，卒后子孝继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','幽',NULL,'幽公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r6','孝','chen-chunqiu','["釐公"]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','幽公之子，在位期间周宣王即位；卒后子灵继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','僖',NULL,'僖公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r7','灵','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','僖公之子，卒后子说继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','武',NULL,'武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('chen-r8','说','chen-chunqiu','[]','媯','陈',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武公之子，在位期间周幽王即位；卒后由弟燮继位。','[{"label":"维基百科：陈国","url":"https://zh.wikipedia.org/wiki/陈国"},{"label":"《史记·陈杞世家》","url":"https://zh.wikisource.org/wiki/史記/卷036"}]','夷',NULL,'夷公','[]');
